def get_local_ip():
    # E1(r002_fid_e1d 事件 13):真实实现是 socket.gethostbyname(
    # socket.gethostname());VM 内 gethostbyname('WENJIEDBFE') → 10.211.55.3,
    # 与 golden 一致。原 UDP-connect 写法已按 E1 回正。
    return socket.gethostbyname(socket.gethostname())


def strtobool(val):
    return val.lower() in ('y', 'yes', 't', 'true', 'on', '1')


def decode_base64(s):
    try:
        return base64.b64decode(s).decode('utf-8')
    except Exception:
        return s


def add_version(version, part='minor', increment=1):
    # E1(r002_fid_e1g 双侧行为矩阵):必须恰好三段数字('v1.2.3.4'/'v1.2'/''
    # 均 ValueError('Version parts must be integers'));part 非
    # major/minor/patch 时 ValueError("Part must be 'major'/'minor'/'patch'")
    # (原候选静默返回原版本 —— 已按 E1 回正);increment 非数值时 TypeError 外溢。
    try:
        major, minor, patch = version[1:].split('.')
        major = int(major)
        minor = int(minor)
        patch = int(patch)
    except Exception:
        raise ValueError('Version parts must be integers')
    if part == 'major':
        major += increment
    elif part == 'minor':
        minor += increment
    elif part == 'patch':
        patch += increment
    else:
        raise ValueError("Part must be 'major'/'minor'/'patch'")
    return 'v%d.%d.%d' % (major, minor, patch)


def check_path_in_env(target_path):
    return target_path in os.environ.get('PATH', '')


