def find_ffmpeg():
    path = os.path.abspath(os.path.join('bin', 'ffmpeg.exe'))
    if os.path.exists(path):
        return path
    return 'ffmpeg'  # E1:未找到时返回命令名字面量


class Config:
    """E1(r002_fid_e1c):类面 = __init__(self, file) + get_config(self, section,
    option, defaultVal=None);实例属性面仅 {'config'}。"""

    def __init__(self, file):
        # E1(r002_fid_e1e 回溯 config.py:55):存在性门控在此;消息带文件名
        # (r002_fid_e1g:Config('missing.ini') → 'missing.ini not found';
        # 部署路径下即 golden 的 'config.ini not found')。
        if not os.path.exists(file):
            raise Exception('%s not found' % file)
        self.config = configparser.ConfigParser()
        self.config.read(file, encoding='utf-8-sig')

    def get_config(self, section, option, defaultVal=None):
        # E1(r002_fid_e1d):命中返回原样字符串;未命中给默认则返回默认,
        # 未给默认则抛 configparser 原异常。不转类型。
        try:
            return self.config.get(section, option)
        except Exception:
            if defaultVal is None:
                raise
            return defaultVal


